// Original classroom models. All numerical datasets and reading passages are invented.
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const reset='<button type="button" class="text-button" data-lab-reset>Reset activity</button>';
const msg='<p class="lw-msg" role="status" aria-live="polite"></p>';
const n=v=>Number(v.toFixed(3)).toLocaleString();
const slider=(key,label,min,max,val,step=1)=>`<label class="lab-control">${label}<input data-value-input="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${val}"><output data-readout="${key}">${val}</output></label>`;
const get=(r,k)=>Number(r.querySelector(`[data-value-input="${k}"]`).value);
const updateOutputs=r=>r.querySelectorAll('[data-value-input]').forEach(i=>{r.querySelector(`[data-readout="${i.dataset.valueInput}"]`).textContent=i.value;});
const steps=(labels,at)=>`<div class="science-path" role="img" aria-label="${e(labels.join(' then '))}">${labels.map((s,i)=>`<span class="${i<=at?'active':''}">${i+1}. ${e(s)}</span>`).join('')}</div>`;

export function calculateMath(mode,a,b,c){
 if(mode==='concentration')return {answer:a*b/c,unit:'mL',work:`${a} mg × ${b} mL ÷ ${c} mg = ${n(a*b/c)} mL`};
 if(mode==='flow')return {answer:a/b,unit:'mL/h',work:`${a} mL ÷ ${b} h = ${n(a/b)} mL/h`};
 if(mode==='drip')return {answer:a*c/b,unit:'gtt/min',work:`${a} mL × ${c} gtt/mL ÷ ${b} min = ${n(a*c/b)} gtt/min (drops are counted as whole numbers, so round as the problem directs)`};
 if(mode==='dilution'){if(b>=a)return {answer:NaN,unit:'mL',work:`A ${b}% solution cannot be made by diluting a ${a}% stock: dilution only lowers concentration.`};const v=b*c/a;return {answer:v,unit:'mL',work:`C₁V₁ = C₂V₂ → V₁ = ${b}% × ${c} mL ÷ ${a}% = ${n(v)} mL of stock, plus ${n(c-v)} mL of diluent to reach ${c} mL`};}
 return {answer:a*1000,unit:'micrograms',work:`${a} mg × (1000 micrograms / 1 mg) = ${n(a*1000)} micrograms`};
}
const mathlab={label:'Dimensional-analysis laboratory',render:w=>`<div class="subject-lab"><p>Predict the result, then inspect the units. Change one quantity and explain why the answer moves.</p><label class="lab-control">Model<select data-math-mode><option value="conversion" ${w.mode==='conversion'?'selected':''}>Mass conversion</option><option value="concentration" ${w.mode==='concentration'?'selected':''}>Amount and concentration</option><option value="flow" ${w.mode==='flow'?'selected':''}>Volume over time</option><option value="drip" ${w.mode==='drip'?'selected':''}>Gravity drip rate</option><option value="dilution" ${w.mode==='dilution'?'selected':''}>Dilution of a stock solution</option></select></label><div data-math-controls></div><div data-math-path></div><label class="lab-prediction">Your numerical prediction<input type="number" step="any" min="0" data-prediction></label><div class="lw-actions"><button type="button" class="button" data-math-check>Check calculation</button>${reset}</div><div data-math-answer hidden></div>${msg}<p class="lw-note">Invented arithmetic examples, not treatment orders. Model results display up to three decimals; round only as the actual problem directs.</p></div>`,mount(r,w){
 const mode=r.querySelector('[data-math-mode]'),area=r.querySelector('[data-math-controls]');
 const draw=()=>{updateOutputs(r);r.querySelector('[data-math-answer]').hidden=true;r.querySelector('.lw-msg').textContent='';r.querySelector('[data-math-path]').innerHTML=steps(['Identify units','Choose relationship','Calculate','Check magnitude'],1);};
 const setup=()=>{area.innerHTML=mode.value==='concentration'?slider('a','Required amount (mg)',10,200,50,10)+slider('b','Reference volume (mL)',1,10,5)+slider('c','Amount in reference volume (mg)',10,250,100,10):mode.value==='flow'?slider('a','Total volume (mL)',50,1000,240,10)+slider('b','Duration (h)',1,12,4):mode.value==='drip'?slider('a','Volume to infuse (mL)',50,1000,500,10)+slider('b','Time (min)',30,720,240,30)+slider('c','Drop factor (gtt/mL)',10,60,15,5):mode.value==='dilution'?slider('a','Stock strength (%)',5,100,50,5)+slider('b','Desired strength (%)',1,50,10)+slider('c','Final volume (mL)',50,1000,200,50):slider('a','Mass (mg)',0.1,5,0.5,0.1);r.querySelector('[data-prediction]').value='';draw();};
 mode.addEventListener('change',setup);r.addEventListener('input',ev=>{if(ev.target.matches('[data-value-input]'))draw();});
 r.querySelector('[data-math-check]').addEventListener('click',()=>{const input=r.querySelector('[data-prediction]');if(input.value===''||!input.checkValidity()){input.reportValidity();input.focus();return;}const result=calculateMath(mode.value,get(r,'a'),mode.value==='conversion'?1:get(r,'b'),['concentration','drip','dilution'].includes(mode.value)?get(r,'c'):1),ok=Number.isFinite(result.answer)&&(Math.abs(Number(input.value)-result.answer)<=0.005||(mode.value==='drip'&&Number(input.value)===Math.round(result.answer)));const answer=r.querySelector('[data-math-answer]');answer.textContent=result.work;answer.hidden=false;r.querySelector('[data-math-path]').innerHTML=steps(['Identify units','Choose relationship','Calculate','Check magnitude'],3);const m=r.querySelector('.lw-msg');m.textContent=ok?'Correct. Explain the cancellation and estimate the scale before changing a slider.':'Compare the units and operation with your prediction. Revise and check again.';m.dataset.state=ok?'good':'bad';});
 r.querySelector('[data-lab-reset]').addEventListener('click',()=>{mode.value=w.mode||'conversion';setup();});setup();
}};

export function compareGroups(a,an,b,bn){const ar=100*a/an,br=100*b/bn;return {a:ar,b:br,gap:ar-br,ratio:br===0?null:ar/br};}
const equitylab={label:'Population comparison laboratory',render:()=>`<div class="subject-lab"><p>Compare the same fictional adverse outcome in two populations. Counts alone do not describe the rate, and a measured difference alone does not establish its cause.</p><div class="lab-controls">${slider('a','Group A outcome count',0,100,40)}${slider('an','Group A population',100,1000,200,50)}${slider('b','Group B outcome count',0,100,30)}${slider('bn','Group B population',100,1000,300,50)}</div><div class="equity-bars" role="img" aria-label="Outcome rates per 100 people"><div><span>A</span><i data-group-bar="a"></i><output data-group-rate="a"></output></div><div><span>B</span><i data-group-bar="b"></i><output data-group-rate="b"></output></div></div><p data-equity-stats aria-live="polite"></p><p>Which conclusion is supported?</p><div class="science-choices"><button class="chip" type="button" data-inference="cause">The difference proves one cause</button><button class="chip" type="button" data-inference="describe">Describe the difference, then investigate context</button></div>${msg}${reset}<p class="lw-note">These are crude rates from invented data. Age structure, measurement, time period and access may affect interpretation. A zero reference rate makes a ratio undefined.</p></div>`,mount(r){const draw=()=>{updateOutputs(r);const x=compareGroups(get(r,'a'),get(r,'an'),get(r,'b'),get(r,'bn'));for(const k of ['a','b']){r.querySelector(`[data-group-bar="${k}"]`).style.width=x[k]+'%';r.querySelector(`[data-group-rate="${k}"]`).textContent=n(x[k])+' per 100';}r.querySelector('[data-equity-stats]').textContent=`A minus B: ${n(x.gap)} percentage points. Rate ratio A/B: ${x.ratio===null?'undefined (B = 0)':n(x.ratio)}.`;r.querySelector('.lw-msg').textContent='';};r.addEventListener('input',ev=>{if(ev.target.matches('[data-value-input]'))draw();});r.querySelectorAll('[data-inference]').forEach(b=>b.addEventListener('click',()=>{const ok=b.dataset.inference==='describe',m=r.querySelector('.lw-msg');m.dataset.state=ok?'good':'bad';m.textContent=ok?'Supported. Specify population, outcome and period, then investigate explanations without stereotyping.':'These data describe a difference. They cannot isolate a cause or describe every individual.';}));r.querySelector('[data-lab-reset]').addEventListener('click',()=>{r.querySelectorAll('[data-value-input]').forEach(i=>i.value=i.defaultValue);draw();});draw();}};

const ETHICS=[
 {title:'Choice and communication',facts:'An adult asks for more explanation before deciding about a proposed intervention. The scenario does not establish impaired decision-making capacity.',principle:'Autonomy',wrong:'Efficiency overrides all questions',action:'Provide understandable information, explore questions and use the appropriate consent process.',why:'A request for explanation is not proof of incapacity. Support informed participation and clarify uncertainty.'},
 {title:'Privacy and access',facts:'A staff member wants to view a neighbor’s record out of curiosity. No work-related purpose or authorization is identified.',principle:'Confidentiality',wrong:'Access software establishes permission',action:'Do not access the record; follow the organization’s privacy and reporting process.',why:'Technical ability to open a record does not establish a permitted purpose. Specific legal obligations depend on role and setting.'},
 {title:'Fair allocation',facts:'Two service groups face different transport barriers. A manager proposes one digital-only booking route without examining who can use it.',principle:'Justice',wrong:'Identical process guarantees equitable access',action:'Investigate access barriers with affected people and compare feasible alternatives and consequences.',why:'A consistent process can have unequal effects. Fairness requires relevant criteria and attention to actual access.'}
];
const ethicslab={label:'Ethical reasoning workshop',render:()=>`<div class="subject-lab"><label class="lab-control">Scenario<select data-ethics-scenario>${ETHICS.map((s,i)=>`<option value="${i}">${e(s.title)}</option>`).join('')}</select></label><div data-ethics-path></div><p data-ethics-facts></p><div data-ethics-stage></div>${msg}${reset}<p class="lw-note">Fictional teaching cases. Identify missing facts and consult applicable policy and qualified guidance before making real legal or clinical decisions.</p></div>`,mount(r,w={}){let stage=0;const select=r.querySelector('[data-ethics-scenario]'),start=String(Math.min(ETHICS.length-1,Math.max(0,w.scenario||0))),current=()=>ETHICS[Number(select.value)];select.value=start;const draw=()=>{const c=current();r.querySelector('[data-ethics-path]').innerHTML=steps(['Establish facts','Name the concern','Justify a response'],stage);r.querySelector('[data-ethics-facts]').textContent=c.facts;r.querySelector('[data-ethics-stage]').innerHTML=stage===0?'<button type="button" class="button secondary" data-ethics-next>Identify the ethical concern →</button>':stage===1?`<p>Which concern fits the stated facts?</p><div class="science-choices"><button type="button" class="chip" data-ethics-choice="yes">${e(c.principle)}</button><button type="button" class="chip" data-ethics-choice="no">${e(c.wrong)}</button></div>`:`<p><strong>Reasoned response:</strong> ${e(c.action)}</p><p>${e(c.why)}</p><label class="lab-reflection">What additional fact could change your reasoning?<textarea rows="3" placeholder="Record a missing fact and why it matters."></textarea></label>`;r.querySelector('.lw-msg').textContent='';};r.addEventListener('click',ev=>{if(ev.target.closest('[data-ethics-next]')){stage=1;draw();}const b=ev.target.closest('[data-ethics-choice]');if(!b)return;if(b.dataset.ethicsChoice==='yes'){stage=2;draw();}else{const m=r.querySelector('.lw-msg');m.textContent='Reconsider the person affected and the permission or fairness issue. The facts do not support that shortcut.';m.dataset.state='bad';}});select.addEventListener('change',()=>{stage=0;draw();});r.querySelector('[data-lab-reset]').addEventListener('click',()=>{select.value=start;stage=0;draw();});draw();}};

const DEFAULT_PASSAGES=[{text:'Original practice passage: A clinic sent reminders to 100 people. Seventy attended, compared with sixty of a different 100 people the previous month. Staffing and appointment availability also changed. The report describes attendance, but does not isolate the reminder’s effect.',claim:'The reminder alone caused the improvement.',supported:false,why:'The comparison does not isolate reminders from other changes or differences between groups.'},{text:'Original practice passage: A patient says that a clear explanation helped them ask questions. The account describes one person’s experience. It does not estimate how often every patient receives an understandable explanation.',claim:'This account describes an individual experience rather than a population frequency.',supported:true,why:'A narrative can illuminate an experience without providing a representative rate.'}];
const evidencebench={label:'Evidence and inference bench',render:()=>`<div class="subject-lab"><div data-evidence-path></div><blockquote class="practice-passage" data-evidence-text></blockquote><p data-evidence-claim></p><div class="science-choices"><button type="button" class="chip" data-evidence-answer="true">Supported by this passage</button><button type="button" class="chip" data-evidence-answer="false">Goes beyond this passage</button></div>${msg}<div class="lw-actions"><button class="button secondary" type="button" data-evidence-next>Next passage →</button>${reset}</div><p class="lw-note">Original invented passages, not excerpts or plot summaries from assigned books. Ground your answer in the passage, then verify book-specific evidence in your own copy.</p></div>`,mount(r,w){const passages=w.passages?.length?w.passages:DEFAULT_PASSAGES;let at=0;const draw=()=>{const p=passages[at];r.querySelector('[data-evidence-path]').innerHTML=steps(['Read','Test the claim','Explain the limit'],0);r.querySelector('[data-evidence-text]').textContent=p.text;r.querySelector('[data-evidence-claim]').textContent=p.claim;r.querySelector('.lw-msg').textContent='';r.querySelectorAll('[data-evidence-answer]').forEach(b=>b.setAttribute('aria-pressed','false'));};r.querySelectorAll('[data-evidence-answer]').forEach(b=>b.addEventListener('click',()=>{const p=passages[at],ok=(b.dataset.evidenceAnswer==='true')===p.supported;r.querySelectorAll('[data-evidence-answer]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const m=r.querySelector('.lw-msg');m.textContent=(ok?'Correct. ':'Reconsider the claim. ')+p.why;m.dataset.state=ok?'good':'bad';r.querySelector('[data-evidence-path]').innerHTML=steps(['Read','Test the claim','Explain the limit'],2);}));r.querySelector('[data-evidence-next]').addEventListener('click',()=>{at=(at+1)%passages.length;draw();});r.querySelector('[data-lab-reset]').addEventListener('click',()=>{at=0;draw();});draw();}};

// Align the attempt with the expected spelling (edit distance) so one missing or extra letter
// is marked on its own instead of shifting every later letter out of place.
export function spellingDiff(attempt,expected){
 const a=[...attempt],b=[...expected],m=a.length,n=b.length,d=Array.from({length:m+1},(_,i)=>Array.from({length:n+1},(_,j)=>i===0?j:j===0?i:0));
 for(let i=1;i<=m;i++)for(let j=1;j<=n;j++)d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+(a[i-1]===b[j-1]?0:1));
 const out=[];let i=m,j=n;
 while(i>0||j>0){
  if(i>0&&j>0&&d[i][j]===d[i-1][j-1]+(a[i-1]===b[j-1]?0:1)){out.push({letter:b[j-1],typed:a[i-1],correct:a[i-1]===b[j-1]});i--;j--;}
  else if(j>0&&d[i][j]===d[i][j-1]+1){out.push({letter:b[j-1],typed:'',correct:false,missing:true});j--;}
  else{out.push({letter:'',typed:a[i-1],correct:false,extra:true});i--;}
 }
 return out.reverse();
}
const DEFAULT_WORDS=[['erythrocyte','A red blood cell.'],['ophthalmology','The medical specialty concerned with the eye.'],['cholecystectomy','Surgical removal of the gallbladder.']];
const spellinglab={label:'Spelling retrieval studio',render:w=>`<div class="subject-lab"><p data-spell-clue></p><div class="lw-actions"><button type="button" class="button secondary" data-spell-audio>Hear device pronunciation</button><button type="button" class="text-button" data-spell-hint>Reveal word for study</button></div><p data-spell-hint-text hidden></p><form data-spell-form><label class="lab-prediction">Retrieve the spelling<input type="text" data-spell-input autocomplete="off" autocapitalize="none" spellcheck="false" required></label><button class="button" type="submit">Check spelling</button></form><div class="spelling-diff" data-spell-diff aria-live="polite"></div>${msg}<div class="lw-actions"><button type="button" class="button secondary" data-spell-next>Next term →</button>${reset}</div><p class="lw-note">${w&&w.note?e(w.note):'Definition-led recall practice. Device speech is optional synthetic pronunciation and may be inaccurate; use Taber’s official audio for competition listening practice. This activity does not assess your spoken letters.'}</p></div>`,mount(r,w){const words=w.words?.length?w.words:DEFAULT_WORDS;let at=0;const draw=()=>{r.querySelector('[data-spell-clue]').textContent=words[at][1];r.querySelector('[data-spell-input]').value='';r.querySelector('[data-spell-hint-text]').hidden=true;r.querySelector('[data-spell-hint-text]').textContent=words[at][0];r.querySelector('[data-spell-diff]').replaceChildren();r.querySelector('.lw-msg').textContent='';};r.querySelector('[data-spell-hint]').addEventListener('click',()=>{const p=r.querySelector('[data-spell-hint-text]');p.hidden=!p.hidden;});r.querySelector('[data-spell-audio]').addEventListener('click',()=>{const m=r.querySelector('.lw-msg');if(!('speechSynthesis' in window)){m.textContent='Device speech is unavailable. Use the official audio glossary linked in the lesson resources.';return;}window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(words[at][0]);u.lang='en-US';u.rate=0.8;u.onerror=()=>{if(r.isConnected)m.textContent='Device speech could not play. Use the official audio glossary.';};window.speechSynthesis.speak(u);});r.querySelector('[data-spell-form]').addEventListener('submit',ev=>{ev.preventDefault();const input=r.querySelector('[data-spell-input]'),attempt=input.value.trim().toLowerCase(),expected=words[at][0].toLowerCase(),ok=attempt===expected;if(!attempt){input.reportValidity();return;}r.querySelector('[data-spell-diff]').innerHTML=spellingDiff(attempt,expected).map(x=>`<span class="${x.correct?'correct':x.missing?'incorrect missing':x.extra?'incorrect extra':'incorrect'}" title="${x.missing?'missing letter':x.extra?'extra letter':x.correct?'':'you typed '+e(x.typed)}">${e((x.extra?x.typed:x.letter)===' '?'␣':(x.extra?x.typed:x.letter))}</span>`).join('');const m=r.querySelector('.lw-msg');m.textContent=ok?'Correct. Say the letters aloud, then retrieve the word again without looking.':`Compare with ${words[at][0]}. Highlighted letters are missing (dashed), extra (struck through) or different.${attempt.length>expected.length?' Your answer also contains extra letters.':''} Study the pattern, hide the model and retry.`;m.dataset.state=ok?'good':'bad';});r.querySelector('[data-spell-next]').addEventListener('click',()=>{at=(at+1)%words.length;draw();});r.querySelector('[data-lab-reset]').addEventListener('click',()=>{at=0;draw();});draw();}};

export const SCIENCE_LABS={mathlab,equitylab,ethicslab,evidencebench,spellinglab};
